 50→function normalizePortValue(value: unknown): string | undefined {
 51→  if (typeof value !== "string" && typeof value !== "number") return undefined;
 52→  const parsed = Number.parseInt(String(value), 10);
 53→  if (!Number.isInteger(parsed) || parsed <= 0 || parsed > 65_535) return undefined;
 54→  return String(parsed);
 55→}
