 57→async function readTerminalPort(): Promise<string> {
 58→  try {
 59→    const response = await fetch("/api/runtime/terminal", { cache: "no-store" });
 60→    if (!response.ok) {
 61→      throw new Error(`HTTP ${response.status}`);
 62→    }
 63→    const payload = (await response.json()) as RuntimeTerminalConfig;
 64→    return normalizePortValue(payload.directTerminalPort) ?? "14801";
 65→  } catch {
 66→    return "14801";
 67→  }
 68→}
