 70→function consumeWheelLines(
 71→  event: WheelEvent,
 72→  rows: number,
 73→  rowHeight: number,
 74→  partialScrollRef: { current: number },
 75→): number {
 76→  if (event.deltaY === 0 || event.shiftKey) return 0;
 77→
 78→  if (event.deltaMode === WheelEvent.DOM_DELTA_LINE) {
 79→    return Math.trunc(event.deltaY);
 80→  }
 81→
 82→  if (event.deltaMode === WheelEvent.DOM_DELTA_PAGE) {
 83→    return Math.trunc(event.deltaY * rows);
 84→  }
 85→
 86→  const pixelsPerLine = rowHeight > 0 ? rowHeight : 16;
 87→  partialScrollRef.current += event.deltaY / pixelsPerLine;
 88→  const lines = Math.trunc(partialScrollRef.current);
 89→  partialScrollRef.current -= lines;
 90→  return lines;
 91→}
