 93→export function buildDirectTerminalWsUrl(
 94→  location: TerminalLocation,
 95→  port: string,
 96→  sessionId: string,
 97→): string {
 98→  const protocol = location.protocol === "https:" ? "wss:" : "ws:";
 99→  return `${protocol}//${location.hostname}:${port}/ws?session=${encodeURIComponent(sessionId)}`;
100→}
