102→export function DirectTerminal({ sessionId, label, title, onClose }: DirectTerminalProps) {
103→  const terminalRef = useRef<HTMLDivElement>(null);
104→  const websocketRef = useRef<WebSocket | null>(null);
105→  const [status, setStatus] = useState<"connecting" | "connected" | "error">("connecting");
106→  const [error, setError] = useState<string | null>(null);
107→
108→  const sendTerminalInput = (data: string) => {
109→    if (websocketRef.current?.readyState !== WebSocket.OPEN) return;
110→    websocketRef.current.send(data);
111→  };
112→
113→  useEffect(() => {
114→    if (!terminalRef.current) return;
115→
116→    let mounted = true;
117→    let terminal: TerminalType | null = null;
118→    let fit: FitAddonType | null = null;
119→    let inputDisposable: { dispose(): void } | null = null;
120→    let resizeHandler: (() => void) | null = null;
121→    let terminalViewport: HTMLDivElement | null = null;
122→    let wheelTarget: HTMLElement | null = null;
123→    let wheelHandler: ((event: WheelEvent) => void) | null = null;
124→    const wheelPartialScroll = { current: 0 };
125→
126→    Promise.all([
127→      import("xterm").then((module) => module.Terminal),
128→      import("@xterm/addon-fit").then((module) => module.FitAddon),
