135→          fontSize: 13,
136→          fontFamily:
137→            'var(--font-mono), "JetBrains Mono", "SF Mono", Menlo, Monaco, "Courier New", monospace',
138→          theme: terminalTheme,
139→          minimumContrastRatio: 1,
140→          scrollback: 10_000,
141→          allowProposedApi: true,
142→        });
143→
144→        fit = new FitAddon();
145→        terminal.loadAddon(fit);
146→
147→        terminal.parser.registerCsiHandler({ prefix: ">", final: "q" }, () => {
148→          terminal?.write("\x1bP>|XTerm(370)\x1b\\");
149→          return true;
150→        });
151→
152→        terminal.parser.registerOscHandler(52, (data) => {
153→          const parts = data.split(";");
154→          if (parts.length < 2) return false;
155→          const encoded = parts[parts.length - 1];
156→          if (!encoded) return false;
157→          try {
158→            const binary = atob(encoded);
159→            const bytes = Uint8Array.from(binary, (char) => char.charCodeAt(0));
160→            const text = new TextDecoder().decode(bytes);
161→            void navigator.clipboard?.writeText(text);
162→          } catch {
163→            // Ignore invalid clipboard payloads.
164→          }
165→          return true;
166→        });
167→
168→        terminal.open(terminalRef.current);
169→        terminalViewport = (terminal.element?.querySelector(".xterm-viewport") as HTMLDivElement) ?? null;
170→        fit.fit();
171→
172→        wheelTarget = terminalRef.current;
173→        if (wheelTarget) {
174→          wheelHandler = (event: WheelEvent) => {
175→            if (!terminal) return;
176→            event.preventDefault();
177→            event.stopImmediatePropagation();
178→            const activeBuffer = terminal.buffer.active;
179→            if (activeBuffer.type !== "normal" || activeBuffer.baseY <= 0) {
180→              wheelPartialScroll.current = 0;
181→              return;
182→            }
183→
184→            const rowHeight =
185→              terminalViewport && terminal.rows > 0 ? terminalViewport.clientHeight / terminal.rows : 0;
186→            const lines = consumeWheelLines(event, terminal.rows, rowHeight, wheelPartialScroll);
187→            if (lines !== 0) {
188→              terminal.scrollLines(lines);
189→            }
190→          };
191→          wheelTarget.addEventListener("wheel", wheelHandler, { capture: true, passive: false });
192→        }
193→
194→        const port = await readTerminalPort();
195→        if (!mounted) return;
196→
197→        const wsUrl = buildDirectTerminalWsUrl(window.location, port, sessionId);
198→        const websocket = new WebSocket(wsUrl);
199→        websocketRef.current = websocket;
200→        websocket.binaryType = "arraybuffer";
201→
202→        websocket.onopen = () => {
203→          if (!terminal) return;
204→          setStatus("connected");
205→          setError(null);
206→          websocket.send(
207→            JSON.stringify({
208→              type: "resize",
209→              cols: terminal.cols,
210→              rows: terminal.rows,
211→            }),
212→          );
213→        };
214→
215→        websocket.onmessage = (event) => {
216→          const data =
217→            typeof event.data === "string" ? event.data : new TextDecoder().decode(event.data);
218→          terminal?.write(data);
219→        };
220→
221→        websocket.onerror = () => {
222→          setStatus("error");
223→          setError("Terminal connection failed");
224→        };
225→
226→        websocket.onclose = (event) => {
227→          if (!mounted) return;
228→          setStatus("error");
229→          setError(event.reason || "Terminal disconnected");
230→        };
231→
232→        inputDisposable = terminal.onData((data) => {
233→          if (websocket.readyState === WebSocket.OPEN) {
234→            websocket.send(data);
235→          }
236→        });
237→
238→        resizeHandler = () => {
239→          if (!terminal || !fit || websocket.readyState !== WebSocket.OPEN) return;
240→          fit.fit();
241→          websocket.send(
242→            JSON.stringify({
243→              type: "resize",
244→              cols: terminal.cols,
245→              rows: terminal.rows,
246→            }),
247→          );
248→        };
249→
250→        window.addEventListener("resize", resizeHandler);
251→      })
252→      .catch(() => {
253→        setStatus("error");
254→        setError("Failed to load terminal");
255→      });
256→
257→    return () => {
258→      mounted = false;
259→      if (resizeHandler) {
260→        window.removeEventListener("resize", resizeHandler);
261→      }
262→      if (wheelTarget && wheelHandler) {
263→        wheelTarget.removeEventListener("wheel", wheelHandler, true);
