295→          ) : null}
296→        </div>
297→        <div className="ml-auto text-[10px] font-medium uppercase tracking-[0.06em] text-[var(--color-text-tertiary)]">
298→          {statusText}
299→        </div>
300→        {onClose ? (
301→          <button
302→            aria-label="Close terminal"
303→            className="ml-2 inline-flex h-7 w-7 items-center justify-center rounded-sm text-[var(--color-text-secondary)] transition hover:bg-white/5 hover:text-[var(--color-text-primary)]"
304→            onClick={onClose}
