306→          >
307→            <svg
308→              aria-hidden="true"
309→              className="h-4 w-4"
310→              fill="none"
311→              stroke="currentColor"
312→              strokeWidth="2"
313→              viewBox="0 0 24 24"
314→            >
315→              <path d="M6 6l12 12M18 6L6 18" />
316→            </svg>
317→          </button>
318→        ) : null}
319→      </div>
320→
321→      <div className="min-h-0 flex-1 p-1.5">
322→        <div ref={terminalRef} className="h-full min-h-0" />
323→      </div>
324→
325→      <div className="shrink-0 border-t border-[var(--color-border-default)] bg-[var(--color-bg-base)] px-2 py-1.5">
326→        <div className="flex items-center gap-1">
